  "$.security": {
    "fullName": "$.security",
    "kind": "namespace",
    "description": "Namespace: security",
    "children": [
      {
        "name": "AntiVirus",
        "fullName": "$.security.AntiVirus",
        "kind": "class",
        "description": "Class for checking data with external Anti-Virus (AV) engines. The scan needs a Virus Scan Adapter (VSA) to be installed on the host. The setup and configuration is available with SAP note 2081108 . This class uses the SAP certified interface NW-VSI 2.00 (see SAP note 1883424 ). For a list of the AV products supported, see SAP note 1494278 ."
      },
      {
        "name": "crypto",
        "fullName": "$.security.crypto",
        "kind": "namespace",
        "description": "Namespace: crypto"
      },
      {
        "name": "Store",
        "fullName": "$.security.Store",
        "kind": "class",
        "description": "The secure store API can be used to securely store data in name/value form. Applications can define a secure store object file and refer to this design time object in the application coding. The XSEngine takes care of the encryption and decryption and also provides the persistency for the data. There are two visibility options for the data a) Visible application wide All users of the application share the same data and can decrypt/encrypt data e.g.: passwords for a remote system b) Visible application wide but with a seperation on user level Every user of the application can have it's own encrypted data which can only be decrypted by the user himself e.g. credit card numbers/pin codes etc."
      },
      {
        "name": "x509",
        "fullName": "$.security.x509",
        "kind": "namespace",
        "description": "The textual representation of certificate attributes is different in the crypto toolkits (openssl, commoncrypto). Use this API always if you persit certificate strings, e.g. SQL identity mapping creation, SAML provider creation, etc. It uses the runtime parser which ensures consistent behaviour."
      }
    ],
    "members": [],
    "methods": [],
    "constructors": []
  },
